#!/usr/bin/env bash
set -euo pipefail

# User-local integration generated by the enabled Omarchy plugin.
# The plugin checkout remains the application payload; this helper only creates
# the launcher-facing files required by XDG/Omarchy application discovery.

readonly PLUGIN_ID="io.github.pluseight8.omapath"
readonly APP_ID="dev.omarchy.Omapath"
readonly DESKTOP_ID="${APP_ID}.desktop"
readonly MARKER="X-Omapath-Plugin-Id=${PLUGIN_ID}"

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
PLUGIN_DIR="$(cd -- "$SCRIPT_DIR/.." && pwd -P)"

[[ -n "${HOME:-}" ]] || { echo "desktop-entry: HOME is not set" >&2; exit 1; }

if [[ -n "${XDG_DATA_HOME:-}" && "$XDG_DATA_HOME" == /* ]]; then
  DATA_HOME="$XDG_DATA_HOME"
else
  DATA_HOME="$HOME/.local/share"
fi

if [[ -n "${XDG_BIN_HOME:-}" && "$XDG_BIN_HOME" == /* ]]; then
  BIN_HOME="$XDG_BIN_HOME"
else
  BIN_HOME="$HOME/.local/bin"
fi

DESKTOP_DIR="$DATA_HOME/applications"
DESKTOP_FILE="$DESKTOP_DIR/$DESKTOP_ID"
ICON_DIR="$DATA_HOME/icons/hicolor/scalable/apps"
ICON_FILE="$ICON_DIR/$APP_ID.svg"
PNG_ICON_DIR="$DATA_HOME/icons/hicolor/1024x1024/apps"
PNG_ICON_FILE="$PNG_ICON_DIR/$APP_ID.png"
LAUNCHER="$BIN_HOME/omapath"
SOURCE_SVG="$PLUGIN_DIR/data/icons/hicolor/scalable/apps/$APP_ID.svg"
SOURCE_PNG="$PLUGIN_DIR/data/icons/hicolor/1024x1024/apps/$APP_ID.png"

die() {
  echo "desktop-entry: $*" >&2
  exit 1
}

desktop_escape() {
  local value="$1"
  value=${value//\\/\\\\}
  value=${value//\"/\\\"}
  value=${value//\`/\\\`}
  value=${value//\$/\\\$}
  printf '%s' "$value"
}

atomic_write() {
  local destination="$1"
  local mode="$2"
  local directory temporary
  directory="$(dirname -- "$destination")"
  mkdir -p -- "$directory"
  temporary="$(mktemp --tmpdir="$directory" ".$(basename -- "$destination").XXXXXX")"
  cat >"$temporary"
  chmod "$mode" -- "$temporary"
  mv -f -- "$temporary" "$destination"
}

refresh_desktop_caches() {
  # Omarchy/Quickshell watches desktop entries live. These calls make the same
  # files visible promptly to other launchers too, and are deliberately best-effort.
  if command -v update-desktop-database >/dev/null 2>&1; then
    update-desktop-database "$DESKTOP_DIR" >/dev/null 2>&1 || true
  fi
  if command -v gtk-update-icon-cache >/dev/null 2>&1; then
    gtk-update-icon-cache -f -t "$DATA_HOME/icons/hicolor" >/dev/null 2>&1 || true
  fi
}

install_entry() {
  [[ -x "$PLUGIN_DIR/run.sh" ]] || die "missing executable launcher: $PLUGIN_DIR/run.sh"
  [[ -f "$SOURCE_SVG" ]] || die "missing Omapath SVG icon in plugin checkout"

  if [[ -e "$DESKTOP_FILE" || -L "$DESKTOP_FILE" ]]; then
    [[ -f "$DESKTOP_FILE" ]] || die "refusing to replace non-regular desktop entry: $DESKTOP_FILE"
    grep -Fqx -- "$MARKER" "$DESKTOP_FILE" || \
      die "refusing to replace an unowned desktop entry: $DESKTOP_FILE"
  fi

  mkdir -p -- "$BIN_HOME" "$DESKTOP_DIR" "$ICON_DIR"

  local plugin_run launcher_exec
  plugin_run="$(printf '%q' "$PLUGIN_DIR/run.sh")"
  atomic_write "$LAUNCHER" 0755 <<EOF
#!/usr/bin/env bash
set -euo pipefail
exec $plugin_run "\$@"
EOF

  install -m 0644 -- "$SOURCE_SVG" "$ICON_FILE"
  if [[ -f "$SOURCE_PNG" ]]; then
    mkdir -p -- "$PNG_ICON_DIR"
    install -m 0644 -- "$SOURCE_PNG" "$PNG_ICON_FILE"
  fi

  launcher_exec="$(desktop_escape "$LAUNCHER")"
  atomic_write "$DESKTOP_FILE" 0644 <<EOF
[Desktop Entry]
Type=Application
Name=Omapath
GenericName=File Manager
Comment=The native file manager for Omarchy.
Exec="$launcher_exec" %U
TryExec=$launcher_exec
Icon=$APP_ID
Terminal=false
Categories=FileManager;System;FileTools;
MimeType=inode/directory;
StartupNotify=true
StartupWMClass=$APP_ID
DBusActivatable=false
$MARKER
EOF

  refresh_desktop_caches

  # Make installation failure obvious to the service and to manual diagnostics.
  [[ -s "$DESKTOP_FILE" ]] || die "desktop entry was not created"
  [[ -x "$LAUNCHER" ]] || die "launcher wrapper was not created"
  [[ -s "$ICON_FILE" ]] || die "launcher icon was not created"
}

remove_owned_file() {
  local path="$1"
  [[ -e "$path" || -L "$path" ]] || return 0
  rm -f -- "$path"
}

remove_entry() {
  if [[ -e "$DESKTOP_FILE" || -L "$DESKTOP_FILE" ]]; then
    [[ -f "$DESKTOP_FILE" ]] || die "refusing to remove non-regular desktop entry: $DESKTOP_FILE"
    grep -Fqx -- "$MARKER" "$DESKTOP_FILE" || \
      die "refusing to remove an unowned desktop entry: $DESKTOP_FILE"
    rm -f -- "$DESKTOP_FILE"
  fi

  # These paths are uniquely owned by this plugin integration.
  remove_owned_file "$LAUNCHER"
  remove_owned_file "$ICON_FILE"
  remove_owned_file "$PNG_ICON_FILE"
  refresh_desktop_caches
}

status_entry() {
  local failed=0
  [[ -f "$DESKTOP_FILE" ]] || { echo "missing desktop: $DESKTOP_FILE"; failed=1; }
  [[ -x "$LAUNCHER" ]] || { echo "missing launcher: $LAUNCHER"; failed=1; }
  [[ -f "$ICON_FILE" ]] || { echo "missing icon: $ICON_FILE"; failed=1; }
  if (( failed == 0 )); then
    echo "desktop=$DESKTOP_FILE"
    echo "launcher=$LAUNCHER"
    echo "icon=$ICON_FILE"
  fi
  return "$failed"
}

case "${1:-}" in
  install|update|repair) install_entry ;;
  remove|uninstall) remove_entry ;;
  status) status_entry ;;
  -h|--help)
    printf 'Usage: %s {install|update|repair|remove|status}\n' "$(basename -- "$0")"
    ;;
  *)
    echo "Usage: $0 {install|update|repair|remove|status}" >&2
    exit 2
    ;;
esac
